contracts/Task1Token.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import "./ERC20.sol";

// =============================================================================
// TASK 1. One thing to fill in.
// You deploy this contract twice, once for token A and once for token B.
// =============================================================================

contract ExamToken is ERC20 {
    constructor(string memory name_, string memory symbol_, uint256 initialSupply_)
        ERC20(name_, symbol_, 18)
    {
        // TODO 1.1 --------------------------------------------------------
        // Give the whole initial supply to whoever deploys this token.
        //
        // ERC20.sol gives you an internal function:
        //     _mint(address to, uint256 amount)
        //
        // The person deploying is msg.sender. The amount is initialSupply_.
        // Write one line below.

        _mint(msg.sender, initialSupply_);
    }
}

contracts/ERC20.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @notice Minimal ERC20 base. Extend it and mint your supply in the constructor.
abstract contract ERC20 {
    string public name;
    string public symbol;
    uint8 public immutable decimals;

    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory _name, string memory _symbol, uint8 _decimals) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
    }

    function approve(address spender, uint256 amount) public virtual returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) public virtual returns (bool) {
        // Without this the shortfall shows up as a bare arithmetic panic, which is
        // very hard to read. The usual cause is a number typed with the wrong number
        // of zeros, since this token has 18 decimals.
        require(balanceOf[msg.sender] >= amount, "ERC20: balance too small, check the decimals on the amount");
        balanceOf[msg.sender] -= amount;
        unchecked {
            balanceOf[to] += amount;
        }
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) public virtual returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        require(allowed >= amount, "ERC20: not approved for that amount");
        require(balanceOf[from] >= amount, "ERC20: balance too small, send tokens to that contract first");
        if (allowed != type(uint256).max) allowance[from][msg.sender] = allowed - amount;
        balanceOf[from] -= amount;
        unchecked {
            balanceOf[to] += amount;
        }
        emit Transfer(from, to, amount);
        return true;
    }

    function _mint(address to, uint256 amount) internal virtual {
        totalSupply += amount;
        unchecked {
            balanceOf[to] += amount;
        }
        emit Transfer(address(0), to, amount);
    }
}

